// @vitest-environment jsdom
import { describe, expect, it, vi } from 'vitest';
import { Hud } from './Hud';
import { Scoreboard } from './Scoreboard';
import { LoadingOverlay, MatchResults, PauseOverlay } from './Overlays';

describe('HUD', () => {
  it('renders hole, strokes, shot state and clamped power', () => {
    const hud = new Hud();
    hud.render({ holeNumber: 3, holeCount: 18, holeName: 'Sky Bridge', par: 4, strokes: 2, power: 1.4, canShoot: false });
    expect(hud.element.textContent).toContain('HOLE 3/18 · Sky Bridge · PAR 4');
    expect(hud.element.textContent).toContain('STROKES 2');
    expect(hud.element.textContent).toContain('BALL IN MOTION');
    expect(hud.element.querySelector<HTMLElement>('.power-meter__fill')?.style.width).toBe('100%');
    expect(hud.element.querySelector('[role="meter"]')?.getAttribute('aria-valuenow')).toBe('100');
  });
});

describe('Scoreboard', () => {
  it('sorts players by strokes and renders up to eight rows', () => {
    const board = new Scoreboard();
    const players = Array.from({ length: 9 }, (_, i) => ({ id: String(i), name: `Player ${i}`, color: '#fff', strokes: i + 1, totalStrokes: 20 - i, parDelta: i, status: 'playing' as const }));
    board.render({ players, holeNumber: 2, holeCount: 9 });
    const rows = [...board.element.querySelectorAll<HTMLElement>('.scoreboard__row[data-player-id]')];
    expect(rows).toHaveLength(8);
    expect(rows[0]?.querySelector('.scoreboard__name')?.textContent).toBe('Player 8');
  });
});

describe('overlays', () => {
  it('wires pause resume action', () => {
    const resume = vi.fn();
    const pause = new PauseOverlay(resume);
    const button = [...pause.element.querySelectorAll('button')].find(node => node.textContent === 'RESUME');
    button?.click();
    expect(resume).toHaveBeenCalledOnce();
  });

  it('renders loading progress', () => {
    const loading = new LoadingOverlay();
    loading.render(.42, 'Loading hole 4');
    expect(loading.element.textContent).toContain('Loading hole 4');
    expect(loading.element.querySelector<HTMLElement>('.loading-progress__fill')?.style.width).toBe('42%');
  });

  it('renders ranked match results and rewards', () => {
    const results = new MatchResults();
    results.render({ courseName: 'Aurora Circuit', holesPlayed: 18, players: [
      { id:'p1', name:'Ace', color:'#fff', strokes:3, totalStrokes:48, parDelta:-6, status:'finished', rank:1, ratingBefore:1200, ratingAfter:1224, xpEarned:180 },
      { id:'p2', name:'Bot', color:'#000', strokes:4, totalStrokes:53, parDelta:-1, status:'finished', rank:2, ratingBefore:1210, ratingAfter:1202, xpEarned:90 },
    ] });
    expect(results.element.textContent).toContain('MATCH COMPLETE');
    expect(results.element.textContent).toContain('Aurora Circuit');
    expect(results.element.textContent).toContain('Rating 1224 (+24)');
    expect(results.element.textContent).toContain('+180 XP');
    expect(results.element.querySelector('.is-winner .results-name')?.textContent).toBe('Ace');
  });
});
